import { describe, expect, it } from 'vitest';
import { parseGcodeFooter, parseGcodeHeader } from './gcodeInfo';

const header = `; HEADER_BLOCK_START
; generated by Creality_Print V6.1.1.2275 on 2025-06-13 at 14:42:49
; total layer number: 62
; HEADER_BLOCK_END

; THUMBNAIL_BLOCK_START
; thumbnail begin 96x96 8
; AAAASMAL
; thumbnail end
; thumbnail begin 300x300 12
; BBBB
; BBBBBBBB
; thumbnail end
; THUMBNAIL_BLOCK_END
G28
`;

const footer = `; filament used [mm] = 6258.25
; filament used [g] = 18.67
; estimated printing time (normal mode) = 32m 19s
; filament_type = PLA
`;

describe('parseGcodeHeader', () => {
  it('lee capas y la miniatura más grande', () => {
    const info = parseGcodeHeader(header);
    expect(info.layers).toBe(62);
    expect(info.thumbnail).toBe('data:image/png;base64,BBBBBBBBBBBB');
  });
  it('archivo sin cabecera de Creality', () => {
    expect(parseGcodeHeader('G28\nG1 X10\n')).toEqual({});
  });
  it('miniatura cortada por el límite del rango se ignora', () => {
    const cut = '; thumbnail begin 96x96 4132\n; iVBORw0KGgo\n';
    expect(parseGcodeHeader(cut).thumbnail).toBeUndefined();
  });
});

const cura = `;FLAVOR:Marlin
;TIME:1710
;Filament used: 5.28041m
;Layer height: 0.2
;TARGET_MACHINE.NAME:Creality K2 SE
;Generated with Cura_SteamEngine 5.14.0
M140 S60
;LAYER_COUNT:67
;LAYER:0
`;

describe('archivos de Cura', () => {
  it('lee tiempo, filamento y capas de la cabecera de Cura', () => {
    expect(parseGcodeHeader(cura)).toEqual({ layers: 67, estimatedSeconds: 1710, filamentMeters: 5.28041 });
  });
  it('el pie no pisa los datos de Cura con vacíos', () => {
    expect(parseGcodeFooter(';SETTING_3 {"x": 1}\n')).toEqual({});
  });
});

describe('parseGcodeFooter', () => {
  it('lee tiempo, gramos y material', () => {
    expect(parseGcodeFooter(footer)).toEqual({ estimatedSeconds: 1939, filamentGrams: 18.67, filamentType: 'PLA' });
  });
  it('acepta el formato de Orca/Prusa sin "(normal mode)"', () => {
    expect(parseGcodeFooter('; estimated printing time = 1h 2m 3s\n').estimatedSeconds).toBe(3723);
  });
  it('sin datos', () => expect(parseGcodeFooter('G1 X0\n')).toEqual({}));
});
